import{_ as s,o as t,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const k=JSON.parse('{"title":"用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包","description":"","frontmatter":{},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包.md","lastUpdated":1790163617000}'),p={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包.md"};function n(d,a,l,o,h,c){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="用前端视角理解-maven-像-pnpm-一样下载依赖、编译、测试、打包" tabindex="-1">用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包 <a class="header-anchor" href="#用前端视角理解-maven-像-pnpm-一样下载依赖、编译、测试、打包" aria-label="Permalink to &quot;用前端视角理解 Maven：像 pnpm 一样下载依赖、编译、测试、打包&quot;">​</a></h1><p>你可以把 Maven 理解成：</p><blockquote><p>Java 世界里的 <code>pnpm + package.json scripts + tsc/vite + test runner</code> 的组合调度器。</p></blockquote><p>它不是 Java，也不是 Spring Boot。它负责把一个 Java 项目“下载依赖、编译、测试、打包”。</p><p>对应到你熟悉的前端：</p><table tabindex="0"><thead><tr><th>前端</th><th>Java/Maven</th></tr></thead><tbody><tr><td><code>package.json</code></td><td><code>pom.xml</code></td></tr><tr><td>npm registry</td><td>Maven Central/私有 Maven 仓库</td></tr><tr><td><code>pnpm install</code></td><td>Maven 自动下载依赖</td></tr><tr><td><code>node_modules</code> / pnpm store</td><td>本机 Maven 仓库 <code>.m2/repository</code></td></tr><tr><td><code>pnpm test</code></td><td><code>mvn test</code></td></tr><tr><td><code>pnpm build</code></td><td><code>mvn package</code></td></tr><tr><td><code>dist/</code></td><td><code>target/</code></td></tr><tr><td>npm 包版本</td><td><code>groupId + artifactId + version</code></td></tr><tr><td>构建出的前端资源</td><td>构建出的 <code>.jar</code> 服务包</td></tr></tbody></table><p>它们四者的关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Java        = 编程语言</span></span>
<span class="line"><span>JDK         = 编译器 + Java 运行环境</span></span>
<span class="line"><span>Spring Boot = 后端开发框架</span></span>
<span class="line"><span>Maven       = 依赖、编译、测试、打包工具</span></span></code></pre></div><p>例如这个命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maven</span></span></code></pre></div><p>意思只是：</p><blockquote><p>用 macOS 的 Homebrew 安装 Maven 命令行工具。</p></blockquote><p>安装后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>预期看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Apache Maven 3.9.x</span></span>
<span class="line"><span>Java version: 21</span></span></code></pre></div><p>在我们的项目里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>backend/data/pom.xml</span></span></code></pre></div><p>类似一个大型前端 monorepo 的根 <code>package.json</code>，下面管理多个模块：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>futures-data-common</span></span>
<span class="line"><span>futures-data-dal</span></span>
<span class="line"><span>futures-data-job</span></span>
<span class="line"><span>futures-data-gateway</span></span>
<span class="line"><span>futures-data-realtime</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>以后我们会经常执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/data</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> futures-data-job</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>用人话拆开：</p><ul><li><code>-pl futures-data-job</code>：只选择 <code>futures-data-job</code> 模块。</li><li><code>-am</code>：它依赖的内部模块也一起构建。</li><li><code>test</code>：编译并运行测试。</li></ul><p>它类似前端 monorepo 中：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> futures-data-job...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>而：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>类似：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>成功后通常得到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>target/futures-data-job.jar</span></span></code></pre></div><p>这个 JAR 就像前端的 <code>dist/</code>，但它是可以通过下面命令启动的后端服务包：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/futures-data-job.jar</span></span></code></pre></div><p>所以 Maven 的核心价值不是“帮你写 Java”，而是保证开发机、测试环境和 CI 使用同一套依赖与构建流程。</p><p>现在先执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maven</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>把 <code>mvn -version</code> 的输出发给我，我们接着亲手验证：项目里的测试到底有没有真的运行。</p>`,38)])])}const g=s(p,[["render",n]]);export{k as __pageData,g as default};
